-- CHALLENGES HANG ON THE CEREMONY SEQUENCE.
--
-- Build order item 5 (`WHATS_NEXT_Papic_Build_Order_2026-08-29.md` § 5), and it
-- runs after 4a because it is 4a's clock that the sequence drives. Prefix
-- allocated by `pnpm migration:new`. Idempotent throughout.
--
-- ═══════════════════════════════════════════════════════════════════════════
-- WHAT WAS MISSING, MEASURED 2026-09-01
-- ═══════════════════════════════════════════════════════════════════════════
-- `lib/kwento-moments.ts` carries the sequence in order — bridal march · vows ·
-- veil & cord · first kiss · leaving the church · cocktail hour · newlywed
-- entrance · first dance · cake cutting · money dance — with NO time on it.
-- `papic_challenge_library` carries 631 prompts. NOTHING JOINED THEM: zero
-- references to kwento anywhere in the pool, and the library's `category` axis
-- is THEMATIC, not ceremonial. `big_moments` and `band_dance` sit ADJACENT to
-- the sequence and are not a mapping — reading either as one is how this item
-- gets reported as already done.
--
-- 🛑 `kwento_assignments.moment_key` IS NOT THIS. It ships (20270120760120) and
-- it assigns a GUEST to a moment so they will write an editorial story about
-- its photo. It answers "who is writing about the first dance?"; this migration
-- answers "what is the room being asked to shoot during it?". Same ten keys,
-- two unrelated questions. The column name is reused deliberately so the
-- vocabulary stays one vocabulary, and for no other reason.
--
-- ═══════════════════════════════════════════════════════════════════════════
-- TWO COLUMNS, TWO DIFFERENT FACTS — NEITHER DERIVABLE FROM THE OTHER
-- ═══════════════════════════════════════════════════════════════════════════
--   `papic_challenge_library.moment_keys`  — which moments a prompt SUITS.
--        Authored ONCE in apps/web/lib/papic-challenge-pool.ts
--        (`MOMENT_CHALLENGES`) and GENERATED into the INSERT at the bottom of
--        this file, exactly as `event_types` is. Global; the same for every
--        celebration.
--   `papic_missions.moment_key`            — which moment a coordinator PUT
--        this challenge at, for THIS celebration. Per-event; a choice, not a
--        property.
--
-- 🔑 THE SECOND ONE IS NOT REDUNDANT, AND THE REASON IS THE DEGRADE RULE. An
-- UNMAPPED moment must fall back to the general pool rather than to nothing
-- (§ 5). A coordinator who takes that fallback has placed a prompt whose
-- `moment_keys` does not name the moment — so deriving the run of show from
-- `moment_keys` alone would lose exactly the choices the fallback exists to
-- make possible, and the moment would read as empty on the next page load.
--
-- ═══════════════════════════════════════════════════════════════════════════
-- 🔴 NO DURATION, NO EXPIRY, NOTHING NEW ABOUT TIME (owner, 2026-09-01)
-- ═══════════════════════════════════════════════════════════════════════════
-- THE SEQUENCE IS THE CLOCK. A moment arms its challenge through
-- `papic_arm_challenge()`, which already closes the previous one; openness is
-- still decided by `papic_challenge_is_open()` and by nothing else. This
-- migration adds no second answer to "is it open?", no duration column, and no
-- default duration number. Expiry closes the PROMPT, never the SHUTTER — no
-- capture path is touched here either.
--
-- RLS: none is added, and that is the answer rather than an omission.
-- `papic_missions` carries Pattern B (`papic_missions_member_all`, FOR ALL, no
-- column scoping), so `moment_key` is governed by it the moment it exists.
-- `papic_challenge_library` carries its own read-only policy (SELECT to
-- authenticated, no write policy), so `moment_keys` is readable exactly where
-- the rest of the row is. The § 5 mapping rows for both tables are unchanged.

BEGIN;

-- ═══════════════════════════════════════════════════════════════════════════
-- 1 · WHICH MOMENTS A PROMPT SUITS
-- ═══════════════════════════════════════════════════════════════════════════
-- ⚠ NULL IS THE RESTRICTIVE VALUE HERE, THE OPPOSITE OF `event_types`. A row
-- with no moments is not "fits every moment" — it is "not one of the run of
-- show's suggestions", which is true of 594 of the 631. Getting this backwards
-- would offer a coordinator the entire library at every moment, which is the
-- blank page the feature exists to remove.
ALTER TABLE public.papic_challenge_library
  ADD COLUMN IF NOT EXISTS moment_keys text[];

COMMENT ON COLUMN public.papic_challenge_library.moment_keys IS
  'Which ceremony moments (lib/kwento-moments.ts keys) this prompt SUITS. NULL '
  '= none; it is still reachable through the picker and the board, it is just '
  'not a run-of-show suggestion. ⚠ NULL is RESTRICTIVE here, unlike '
  'event_types where NULL is permissive. Authored in '
  'apps/web/lib/papic-challenge-pool.ts (MOMENT_CHALLENGES) and generated into '
  'the seed — never hand-written in SQL. NOT the coordinator''s choice: that is '
  'papic_missions.moment_key.';

-- Containment (`moment_keys @> ARRAY[…]`) is the only shape this is ever
-- queried by, and GIN is what answers it without reading 631 rows.
CREATE INDEX IF NOT EXISTS papic_challenge_library_moment_keys_idx
  ON public.papic_challenge_library USING GIN (moment_keys);

-- ═══════════════════════════════════════════════════════════════════════════
-- 2 · WHICH MOMENT A COORDINATOR PUT THIS CHALLENGE AT
-- ═══════════════════════════════════════════════════════════════════════════
-- RULE 0.3 — a flag beats new schema. This belongs on the row that already
-- holds the prompt, the board slot and (since 4a) the clock. A side table
-- `event_id × moment_key × mission_id` would hold the same fact one join away
-- and could disagree with the mission's own existence.
ALTER TABLE public.papic_missions
  ADD COLUMN IF NOT EXISTS moment_key TEXT;

COMMENT ON COLUMN public.papic_missions.moment_key IS
  'The ceremony moment this challenge is placed at for THIS celebration (a '
  'lib/kwento-moments.ts key), or NULL if it is not in the run of show. A '
  'CHOICE, per event — papic_challenge_library.moment_keys is the global fact '
  'about which moments a prompt suits, and a coordinator may place a prompt '
  'that suits none (the degrade path, § 5: an unmapped moment falls back to the '
  'general pool rather than to nothing). Carries NO time of its own: the moment '
  'arms its challenge through papic_arm_challenge() and openness stays '
  'papic_challenge_is_open()''s alone.';

-- ── ONE CHALLENGE PER MOMENT, ENFORCED BY THE DATABASE ─────────────────────
-- The run of show has one prompt at each moment: "each moment arms ITS
-- challenge" (§ 5). Partial, so the overwhelming majority of missions — which
-- are not in a run of show at all — are unaffected and may coexist freely.
-- Same posture as 4a's `papic_missions_one_armed_per_event`: a rule the
-- database refuses to break rather than a convention every writer must recall.
CREATE UNIQUE INDEX IF NOT EXISTS papic_missions_one_challenge_per_moment
  ON public.papic_missions (event_id, moment_key)
  WHERE moment_key IS NOT NULL;

COMMENT ON INDEX public.papic_missions_one_challenge_per_moment IS
  'One challenge per ceremony moment per celebration. Partial: a mission with '
  'no moment_key is not in the run of show and does not occupy a slot.';

-- ⚠ THE KEY IS CHECKED, BECAUSE A TYPO WOULD BE INVISIBLE. A moment_key that
-- matches no KwentoMoment would store cleanly, occupy the unique slot, and
-- render nowhere — a challenge the coordinator believes is placed and that no
-- screen will ever show. The ten keys are LOCKED (the editorial sequence, also
-- used by kwento_assignments), so a CHECK is honest here in a way it would not
-- be for an open vocabulary.
-- 🔑 The list is stated in ONE place per store: here for the database, and
-- KWENTO_MOMENTS for the application. `the-sequence-is-the-clock.db.test.ts`
-- asserts the two are the same ten, so they cannot drift.
ALTER TABLE public.papic_missions
  DROP CONSTRAINT IF EXISTS papic_missions_moment_key_check;
ALTER TABLE public.papic_missions
  ADD CONSTRAINT papic_missions_moment_key_check
  CHECK (moment_key IS NULL OR moment_key IN (
    'bridal_march', 'exchange_of_vows', 'veil_and_cord', 'first_kiss',
    'leaving_the_church', 'cocktail_hour', 'newlywed_entrance', 'first_dance',
    'cake_cutting', 'money_dance'
  ));

COMMIT;

-- ── 3 · THE POOL, RE-STATED WITH ITS MOMENTS ───────────────────────────────
-- ⚠ GENERATED. Do not edit the block below by hand — regenerate it:
--     node --import tsx scripts/emit-papic-challenge-pool.mjs
-- Every row is re-stated because the UPSERT is how a column reaches rows that
-- already exist in production; 20271154904649 stays exactly as it was applied.
BEGIN;
-- GENERATED by scripts/emit-papic-challenge-pool.mjs — DO NOT EDIT BY HAND.
-- Source of truth: apps/web/lib/papic-challenge-pool.ts (631 challenges).
ON CONFLICT (library_id) DO UPDATE SET
  slug          = EXCLUDED.slug,
  category      = EXCLUDED.category,
  title         = EXCLUDED.title,
  prompt        = EXCLUDED.prompt,
  capture_kind  = EXCLUDED.capture_kind,
  mission_type  = EXCLUDED.mission_type,
  priority_rank = EXCLUDED.priority_rank,
  event_types   = EXCLUDED.event_types,
  moment_keys   = EXCLUDED.moment_keys;
COMMIT;
